<script setup lang="ts">
import {computed,ref} from 'vue';import {useCoffee} from '../stores/coffee';import {money,dailyReport,localDate,localTime,csvCell,reportingBranches} from '../../../../packages/shared/src/domain';import Icon from '../components/Icon.vue';
const s=useCoffee();const date=ref(localDate());const branch=ref('all');const allowed=computed(()=>reportingBranches(s.state.branches,branch.value));const ids=computed(()=>allowed.value.map(b=>b.id));const report=computed(()=>dailyReport(s.state.transactions,date.value,ids.value));
const orders=computed(()=>s.state.orders.filter(o=>ids.value.includes(o.branchId)&&o.receiptAt&&localDate(o.receiptAt)===date.value));const saleOrders=computed(()=>s.state.orders.filter(o=>ids.value.includes(o.branchId)&&localDate(o.createdAt)===date.value&&o.state!=='pending'&&o.state!=='cancelled'));const sales=computed(()=>saleOrders.value.reduce((n,o)=>n+o.total,0));const debt=computed(()=>saleOrders.value.reduce((n,o)=>n+Math.max(0,o.total-o.paid),0));
const rows=computed(()=>allowed.value.map(b=>({...b,...dailyReport(s.state.transactions,date.value,[b.id]),bills:orders.value.filter(o=>o.branchId===b.id).length})));
function exportCsv(){const header=['Cơ sở','Bill đã xuất','Tiền mặt','Chuyển khoản','Hoàn tiền','Tiền thực thu'];const text='\uFEFF'+[header,...rows.value.map(r=>[r.name,r.bills,r.cash,r.transfer,r.refunds,r.net])].map(row=>row.map(csvCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='thu-ngay-'+date.value+'.csv';a.click();URL.revokeObjectURL(url)}
</script><template><div class="page dashboard-page"><div class="page-heading"><div><div class="section-kicker">Quản trị quán</div><h2>Tổng quan trong ngày</h2><p>Mỗi cơ sở một góc nhìn. Mọi khoản thu đều rõ ràng.</p></div><div class="filters"><input type="date" v-model="date" aria-label="Ngày báo cáo"><select v-model="branch" aria-label="Cơ sở báo cáo"><option value="all">Tất cả cơ sở</option><option v-for="b in s.state.branches" :key="b.id" :value="b.id">{{b.name}}{{!b.active?' (ngừng hoạt động)':''}}</option></select><button class="btn outline" @click="exportCsv"><Icon name="download" :size="17"/>Xuất báo cáo</button></div></div><div class="metric-grid"><article class="metric primary-metric"><span class="metric-icon"><Icon name="wallet" :size="25"/></span><div><span>Tiền thực thu</span><strong>{{money(report.net)}}</strong><small>Sau các khoản hoàn tiền trong ngày</small></div></article><article class="metric"><span class="metric-icon"><Icon name="wallet"/></span><div><span>Tiền mặt</span><strong>{{money(report.cash)}}</strong><small>Đã trừ tiền trả lại cho khách</small></div></article><article class="metric"><span class="metric-icon"><Icon name="bank"/></span><div><span>Chuyển khoản</span><strong>{{money(report.transfer)}}</strong><small>Theo giao dịch đã lưu xác nhận</small></div></article><article class="metric"><span class="metric-icon"><Icon name="receipt"/></span><div><span>Bill đã xuất</span><strong>{{orders.length}}</strong><small>Không tính thêm bản in lại</small></div></article></div><section class="panel"><div class="panel-heading"><div><h3>Tiền thu theo cơ sở</h3><p>{{date}} · Theo giờ Việt Nam</p></div><span class="status served">{{allowed.length}} cơ sở</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Cơ sở</th><th>Bill</th><th>Tiền mặt</th><th>Chuyển khoản</th><th>Hoàn tiền</th><th>Tổng thực thu</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.name}}{{!r.active?' (ngừng hoạt động)':''}}</strong><small>{{r.address}}</small></td><td>{{r.bills}}</td><td class="numeric">{{money(r.cash)}}</td><td class="numeric">{{money(r.transfer)}}</td><td class="numeric">{{money(r.refunds)}}</td><td class="numeric strong teal">{{money(r.net)}}</td></tr></tbody></table></div><footer class="summary-strip"><div><span>Doanh thu bán hàng</span><strong>{{money(sales)}}</strong></div><div><span>Hoàn tiền trong ngày</span><strong>{{money(report.refunds)}}</strong></div><div><span>Chưa thu của đơn ngày này</span><strong class="amber">{{money(debt)}}</strong></div></footer></section><section class="panel"><div class="panel-heading"><div><h3>Bill trong ngày</h3><p>Chọn bill để xem món, số tiền và lịch sử thanh toán.</p></div><RouterLink class="text-link" to="/admin/receipts">Xem tất cả <Icon name="next" :size="15"/></RouterLink></div><div class="document-tabs"><button class="selected">Bill bán hàng</button><RouterLink to="/admin/invoices">Hóa đơn điện tử</RouterLink></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Mã bill</th><th>Cơ sở / bàn</th><th>Giờ xuất</th><th>Tổng tiền</th><th>Đã thu</th><th>Thanh toán</th><th></th></tr></thead><tbody><tr v-for="o in orders.slice(0,6)" :key="o.id"><td class="strong">{{o.number}}</td><td>{{s.state.branches.find(b=>b.id===o.branchId)?.name}}<small>{{o.tableName}}</small></td><td>{{localTime(o.receiptAt!)}}</td><td class="numeric">{{money(o.total)}}</td><td class="numeric">{{money(o.paid)}}</td><td><span class="status" :class="o.paid>=o.total?'served':'pending'">{{o.paid>=o.total?'Đã thu đủ':'Còn phải thu'}}</span></td><td><RouterLink :to="'/receipt/'+o.id" class="text-link">Xem</RouterLink></td></tr></tbody></table><div v-if="!orders.length" class="empty"><Icon name="receipt" :size="36"/><h3>Chưa có bill đã xuất ngày này</h3><p>Chọn ngày khác hoặc lưu thanh toán từ POS.</p></div></div></section><div class="admin-shortcuts"><RouterLink to="/admin/products"><Icon name="coffee"/>Quản lý thực đơn<Icon name="next"/></RouterLink><RouterLink to="/admin/banks"><Icon name="bank"/>Ngân hàng nhận tiền<Icon name="next"/></RouterLink><RouterLink to="/admin/printers"><Icon name="printer"/>Máy in & hàng đợi<Icon name="next"/></RouterLink></div></div></template>
